messages.content:
{
  "intent": "troubleshoot_no_service",
  "explanation": "No Service can be caused by device settings (Airplane Mode, SIM issues, incorrect network/APN), local coverage, or an account/line problem (suspension, contract end). I’ll check your account/line status and, in parallel, guide you through quick device checks so we can restore service fast.",
  "request_identification": {
    "why": "I must identify your account to check line status, suspensions, roaming, and any billing flags.",
    "provide_one_of": [
      "Phone number of the affected line (preferred)",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ]
  },
  "quick_checks": [
    {
      "step": "Check Airplane Mode",
      "how": "Open Settings → Network/Internet (or Connections) and ensure Airplane Mode is OFF.",
      "tell_me": "Was Airplane Mode ON or OFF?"
    },
    {
      "step": "Read the status bar",
      "how": "Look at the top of the screen.",
      "tell_me": "Do you see: an airplane icon, signal bars (none/1/2/3/4), a network label (5G/4G/3G/2G), or a message like “No SIM” or “Emergency calls only”?"
    },
    {
      "step": "SIM status",
      "how": "Settings → About phone → SIM status (or Cellular/Mobile network → SIM).",
      "tell_me": "Does it say Active, Missing/Not inserted, or Locked (PIN/PUK)?"
    },
    {
      "step": "Mobile data switch",
      "how": "Settings → Network/Internet → Mobile network → turn Mobile Data ON.",
      "tell_me": "Was Mobile Data OFF or ON?"
    },
    {
      "step": "Reboot",
      "how": "Restart the phone once and check if service returns after 1–2 minutes.",
      "tell_me": "Did rebooting change anything?"
    }
  ],
  "additional_questions": [
    "What city/area are you currently in, and is this location where you usually have coverage?",
    "Are you traveling outside your home country/network right now?",
    "Have you recently changed your SIM, plan, or received any overdue bill notices?",
    "Do others around you (same carrier) have service?"
  ],
  "next_step_after_you_reply": "I will look up your account/line with the details you provide, check for any suspensions or roaming settings, and continue targeted troubleshooting (SIM/APN/network mode) based on your quick-check results."
}

