messages.content:
{
  "intent": "troubleshoot_no_service",
  "what_i_checked": {
    "account_lookup": "Found your account via 555-123-2002.",
    "line_status": "Your line (L1002) is Active, not suspended, contract valid, roaming is enabled.",
    "implication": "Since the account/line is OK, the issue is most likely on-device (SIM, network mode/APN) or temporary local coverage."
  },
  "what_im_thinking": "Rule out SIM problems first, then refresh network selection and APN. These are the fastest, most common fixes for a sudden No Service state when the line is active.",
  "questions_before_next_steps": [
    "Where are you located right now, and is this a place where you usually have coverage?",
    "Are you currently traveling outside your home country/network?",
    "Are you connected to Wi‑Fi at the moment? (If yes, we can enable Wi‑Fi Calling so you can make calls while we fix cellular.)"
  ],
  "next_steps_for_you": [
    {
      "step": "Check SIM status",
      "why": "A loose/missing or locked SIM will cause No Service.",
      "how": "Settings → About phone → SIM status (or Cellular/Mobile network → SIM).",
      "tell_me": "Does it say Active, Missing/Not inserted, or Locked (PIN/PUK)?"
    },
    {
      "step": "Quick network refresh",
      "why": "Forces the phone to re-register on the network.",
      "how": "Toggle Airplane Mode ON for 10 seconds, then OFF. Wait 1–2 minutes and check if bars return."
    },
    {
      "step": "If SIM is Missing/Not inserted",
      "why": "Reseating fixes many recognition issues, especially after recent SIM changes.",
      "how": "Power off the phone → remove the SIM tray → reinsert the SIM firmly → power on → wait 1–2 minutes and check the status bar."
    },
    {
      "step": "If SIM is Locked",
      "why": "A PIN/PUK lock blocks network access.",
      "how": "Tell me exactly what it shows (PIN or PUK needed). We’ll connect you to a human agent for SIM security if required."
    },
    {
      "step": "Ensure modern network mode",
      "why": "Being stuck on an old mode can prevent registration.",
      "how": "Settings → Network/Internet → Mobile network → Preferred network type → select 4G/5G (5G/4G/LTE/NR or similar)."
    },
    {
      "step": "Reset APN to default (if still No Service)",
      "why": "Incorrect APN can block registration/data.",
      "how": "Settings → Mobile network → Access Point Names → Reset to default. Then restart the phone once."
    },
    {
      "step": "Optional: Enable Wi‑Fi Calling (temporary workaround)",
      "why": "Lets you make/receive calls over Wi‑Fi while cellular is down.",
      "how": "Settings → Network/Internet (or Connections) → Wi‑Fi Calling → turn ON."
    }
  ],
  "please_reply_with": [
    "Your SIM status result (Active/Missing/Locked).",
    "Your location and whether you’re traveling.",
    "Whether Airplane Mode toggle or a reboot changed anything.",
    "If you prefer, I can also guide you step‑by‑step through any one of the actions above."
  ]
}

