  "steps": [
    {
      "step": "Turn ON Data Roaming on the phone",
      "iphone": "Settings > Cellular > Cellular Data Options > Data Roaming > turn ON.",
      "android": "Settings > Network & Internet (or Connections) > Mobile network > Data roaming > turn ON.",
      "why": "Allows data to work on partner networks while abroad."
    },
    {
      "step": "Refresh the connection",
      "actions": [
        "Toggle Mobile Data OFF, wait 10 seconds, then ON.",
        "Turn Airplane Mode ON for 10 seconds, then OFF."
      ],
      "wait": "Wait 1–2 minutes after toggling to let the phone register for roaming data."
    },
    {
      "step": "Network selection to Automatic",
      "iphone": "Settings > Cellular > Network Selection > turn Automatic ON.",
      "android": "Settings > Network & Internet > Mobile network > Network operators > Select automatically.",
      "why": "Ensures your phone connects to the best available French partner network."
    },
    {
      "step": "If still No Connection, temporarily force 4G/LTE",
      "iphone": "Settings > Cellular > Cellular Data Options > Voice & Data > choose LTE/4G.",
      "android": "Settings > Network & Internet > Mobile network > Preferred network type > choose 4G/LTE.",
      "why": "Sometimes 5G roaming isn’t fully available; 4G/LTE often restores data immediately."
    },
    {
      "step": "Test again",
      "how": "Open your browser to fast.com and share the Mbps result. Also tell me what the top bar shows now (bars and 4G/5G)."
