messages.content:
{
  "thought_process": "I located your account and confirmed the affected line (555-123-2002, Line L1002). On our side, your line is Active, not suspended, roaming is enabled, and you’ve used 8.7 GB out of 15 GB this cycle—so you haven’t hit your data limit. Since SMS works and the issue began today, this points to a device-side condition affecting MMS: mobile data off/unstable, network mode stuck on older tech, APN/MMSC misconfigured, Wi‑Fi Calling interference, VPN, or app permissions. We’ll quickly verify service/data first, then check MMS-specific settings.",
  "account_findings": {
    "line_status": "Active",
    "roaming_enabled": true,
    "plan_data_limit_gb": 15,
    "data_used_gb": 8.7,
    "suspension": "None"
  },
  "questions": [
    "When you try to send a picture, do you see a specific error (e.g., ‘Sending…’ then ‘Failed’, or a red exclamation)?",
    "Are you unable to send, receive, or both?"
  ],
  "please_do_these_steps_and_report_back": [
    {
      "step": 1,
      "purpose": "Confirm basic connectivity for MMS",
      "instructions": [
        "Use check_status_bar and tell me: do you see an airplane icon, how many signal bars, and what network type shows (5G/LTE/4G/3G/2G)?",
        "Turn OFF Wi‑Fi temporarily.",
        "Use check_network_status to confirm Mobile Data is ON. If it shows OFF, use toggle_data to turn it ON.",
        "Open a webpage (e.g., example.com) or run run_speed_test and share the result (e.g., no connection/very poor/poor/fair/good/excellent)."
      ]
    },
    {
      "step": 2,
      "purpose": "Make sure the phone isn’t locked to an old network type",
      "instructions": [
        "Use check_network_mode_preference.",
        "If it shows 2G or 3G, use set_network_mode_preference with mode \"4g_5g_preferred\"."
      ]
    },
    {
      "step": 3,
      "purpose": "Quick toggles that commonly unblock MMS",
      "instructions": [
        "Use check_wifi_calling_status. If Wi‑Fi Calling is ON, use toggle_wifi_calling to turn it OFF for this test.",
        "If you use a VPN, use check_vpn_status and, if connected, use disconnect_vpn."
      ]
    }
  ],
  "next_if_needed": [
    {
      "step": 4,
      "when_to_do": "If mobile data works (you can browse or speed test) but MMS still fails",
      "instructions": [
        "Use check_apn_settings and look for the MMSC URL. If MMSC is missing/incorrect, use reset_apn_settings, then use reboot_device."
      ]
    },
    {
      "step": 5,
      "when_to_do": "If APN looks fine but MMS still fails",
      "instructions": [
        "Use check_app_permissions for your messaging app (the default one). Ensure permissions include \"storage\" and \"sms\".",
        "If missing, use grant_app_permission for \"storage\" and \"sms\"."
      ]
    }
  ],
  "what_to_reply_with": [
    "Status bar details (airplane mode, bars, network type).",
    "Whether Mobile Data was ON or OFF and the speed test/web-browse result.",
    "Your network mode preference result.",
    "Whether Wi‑Fi Calling or a VPN was ON.",
    "Any MMS error message and whether it’s send, receive, or both."
  ]
}

