messages.content:
{
  "thought_process": "Your phone is locked to 2G and has very poor data speed. MMS requires mobile data and generally won’t work on 2G. The quickest fix is to switch your network mode to allow 4G/5G, then retest. Your line on our side is Active, not suspended, and you haven’t hit your data limit (8.7/15 GB), so this looks device/network-mode related.",
  "do_now_steps": [
    {
      "step": 1,
      "purpose": "Allow faster networks required for MMS",
      "instructions": [
        "Use set_network_mode_preference with mode: \"4g_5g_preferred\".",
        "Wait ~30 seconds for the phone to register. Check the status bar for 4G/LTE/5G instead of 2G."
      ]
    },
    {
      "step": 2,
      "purpose": "Force a quick reattach if it stays on 2G",
      "instructions": [
        "Use toggle_airplane_mode to turn Airplane Mode ON, wait 10 seconds, then OFF.",
        "Recheck the status bar for 4G/LTE/5G."
      ]
    },
    {
      "step": 3,
      "purpose": "Verify mobile data quality",
      "instructions": [
        "Ensure Wi‑Fi stays OFF and Mobile Data is ON.",
        "Run run_speed_test and share the result.",
        "Try sending a picture message again to a contact (or to yourself)."
      ]
    }
  ],
  "if_still_fails_after_step_3": [
    {
      "step": 4,
      "purpose": "Fix possible MMS APN/MMSC configuration",
      "instructions": [
        "Use check_apn_settings and confirm the MMSC URL is present.",
        "If MMSC is missing/incorrect, use reset_apn_settings.",
        "Then use reboot_device.",
        "After the reboot, try sending an MMS again."
      ]
    }
  ],
  "what_to_report_back": [
    "What network type shows now (4G/LTE/5G vs 2G) and how many signal bars.",
    "The new speed test result.",
    "Whether the MMS sends successfully after changing the network mode.",
    "If you had to check APN: whether MMSC was present, and whether resetting APN + reboot fixed it."
  ]
}

