      "step": 1,
      "purpose": "Verify and fix APN/MMSC settings (critical for MMS)",
      "instructions": [
        "Use check_apn_settings.",
        "Look specifically for the MMSC URL. If it’s missing or looks incorrect, do the following:",
        "- Use reset_apn_settings to restore defaults.",
        "- Then use reboot_device to apply changes.",
        "After the reboot, keep Wi‑Fi OFF and Mobile Data ON, then try sending an MMS again."
      ]
    },
    {
      "step": 2,
      "purpose": "Ensure the messaging app has required permissions",
      "instructions": [
        "Use check_app_permissions with app_name set to \"messaging\" (your default messaging app).",
        "Confirm that both \"storage\" and \"sms\" permissions are granted.",
        "If either is missing, use grant_app_permission for the missing one(s):",
        "- grant_app_permission with permission \"storage\"",
        "- grant_app_permission with permission \"sms\"",
        "Then try sending an MMS again."
      ]
    },
    {
      "step": 3,
      "purpose": "Double-check a known conflict",
      "instructions": [
        "Use check_wifi_calling_status.",
        "If Wi‑Fi Calling shows ON, use toggle_wifi_calling to turn it OFF, then try sending an MMS again."
      ]
    },
    {
      "step": 4,
      "purpose": "Confirm app capability and receiving behavior",
      "instructions": [
        "Use can_send_mms and share the result.",
        "Also, please have someone send you a picture message (or send one to your own number if your app supports it) to test receiving."
      ]
    }
