messages.content:
{
  "message": "Thanks for checking Wi‑Fi and Mobile Data. Since you’re abroad and MMS still won’t send, we’ll verify a few device settings that commonly block MMS while roaming.",
  "thought_process": "Your line is active, roaming is enabled on our side, and you now have 2 GB added. That means the remaining blockers are usually on‑device: Data Roaming switch, network mode (stuck on 2G/3G), Wi‑Fi Calling conflicts, APN/MMSC settings, VPN interference, or app permissions.",
  "step_by_step_checks": [
    {
      "step": "Check roaming/data state",
      "instructions": [
        "Run check_network_status() and share the results: signal strength, network type (e.g., 4G/5G), Mobile Data ON/OFF, and Data Roaming ON/OFF.",
        "If Data Roaming shows OFF, turn it ON using toggle_roaming()."
      ],
      "why": "While abroad, Data Roaming must be ON on the device for MMS to use mobile data."
    },
    {
      "step": "Ensure modern network mode",
      "instructions": [
        "Run check_network_mode_preference(). If it shows 2G or 3G only, change it to set_network_mode_preference(\"4g_5g_preferred\")."
      ],
      "why": "MMS needs at least 3G, and works best on 4G/5G."
    },
    {
      "step": "Temporarily disable Wi‑Fi Calling",
      "instructions": [
        "Run check_wifi_calling_status(). If Wi‑Fi Calling is ON, turn it OFF using toggle_wifi_calling()."
      ],
      "why": "Some devices/carriers have MMS issues over Wi‑Fi Calling, especially when roaming."
    },
    {
      "step": "Verify APN/MMSC",
      "instructions": [
        "Run check_apn_settings() and tell me if an MMSC URL is shown.",
        "If MMSC is missing/blank/incorrect, use reset_apn_settings(), then run reboot_device() to apply changes."
      ],
      "why": "A correct MMSC URL in APN settings is required for MMS."
    },
    {
      "step": "Eliminate VPN as a factor",
      "instructions": [
        "Run check_vpn_status(). If a VPN is connected, use disconnect_vpn()."
      ],
      "why": "VPNs can interfere with MMS/data routing."
    },
    {
      "step": "Confirm messaging app permissions",
      "instructions": [
        "Run check_app_permissions(app_name=\"messaging\"). If Storage and SMS aren’t granted, run:",
        "grant_app_permission(app_name=\"messaging\", permission=\"storage\")",
        "grant_app_permission(app_name=\"messaging\", permission=\"sms\")"
      ],
      "why": "The messaging app needs Storage and SMS permissions to send MMS."
    },
    {
      "step": "Quick data test",
      "instructions": [
        "Run run_speed_test() with Wi‑Fi OFF and share the result.",
        "Then try sending an MMS to yourself and tell me what happens."
      ],
      "why": "Confirms mobile data is active and helps isolate if the issue is MMS‑specific."
    }
    ],
  "what_to_send_back": [
    "The output of check_network_status() including Data Roaming state.",
    "Your network mode preference from check_network_mode_preference().",
    "Wi‑Fi Calling status.",
    "APN/MMSC details or confirmation that you reset APN and rebooted.",
    "VPN status.",
    "Messaging app permissions list.",
    "Speed test result and the latest MMS attempt outcome."
  ],
  "tip": "After making any change above, try sending an MMS (e.g., a small photo) to yourself to test before moving to the next step."
}

