{
  "status_update": "Thanks for confirming. Roaming is enabled on your line and you have 2 GB refueled. Since MMS still fails, we’ll walk through targeted on‑device checks to restore MMS. I’ll explain each step and why.",
  "plan": [
    {
      "step": "Verify mobile data actually works",
      "why": "MMS uses mobile data. If general data isn’t working, MMS won’t either.",
      "do_this": [
        "Run run_speed_test and tell me the result.",
        "Also try loading a web page with Wi‑Fi OFF (e.g., example.com) and confirm if it loads."
      ]
    },
    {
      "step": "Confirm you’re on a suitable network technology",
      "why": "MMS won’t work reliably on 2G and may fail on some 3G networks abroad.",
      "do_this": [
        "Run check_network_mode_preference and share the result.",
        "If it’s not already 4g_5g_preferred, set it using set_network_mode_preference with mode: \"4g_5g_preferred\".",
        "After changing, toggle Airplane Mode ON then OFF using toggle_airplane_mode to refresh the connection, then try sending an MMS once."
      ]
    },
    {
      "step": "Temporarily turn off Wi‑Fi Calling",
      "why": "Some roaming scenarios don’t support MMS over Wi‑Fi Calling routing.",
      "do_this": [
        "Run check_wifi_calling_status. If it’s ON, use toggle_wifi_calling to turn it OFF.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": "Validate APN/MMSC settings",
      "why": "A missing or incorrect MMSC URL will block MMS entirely.",
      "do_this": [
        "Run check_apn_settings and share the APN name and MMSC URL with me.",
        "If MMSC is missing/blank/looks wrong: run reset_apn_settings, then run reboot_device.",
        "After the reboot, keep Wi‑Fi OFF, ensure Mobile Data + Data Roaming are ON, and try sending an MMS again."
      ]
    },
    {
      "step": "Check VPN and Data Saver",
      "why": "A VPN or Data Saver can interfere with data flows used by MMS.",
      "do_this": [
        "Run check_vpn_status. If a VPN is connected, use disconnect_vpn and retry MMS.",
        "Run check_data_restriction_status. If Data Saver is ON, use toggle_data_saver_mode to turn it OFF and retry MMS."
      ]
    },
    {
      "step": "Confirm messaging app permissions",
      "why": "The app needs storage and SMS permissions to handle media and send MMS.",
      "do_this": [
        "Run check_app_permissions with app_name: \"messaging\".",
        "If \"storage\" or \"sms\" are missing, grant them using grant_app_permission for each missing permission.",
        "Retry sending an MMS."
      ]
    },
    {
      "step": "Quick MMS capability test",
      "why": "Confirms if the device now sees MMS as sendable.",
      "do_this": [
        "Run can_send_mms and share the result."
      ]
    }
    ],
  "please_reply_with": [
    "run_speed_test result and whether a web page loads on mobile data.",
    "check_network_mode_preference result (and confirm if you set 4g_5g_preferred).",
    "Whether Wi‑Fi Calling was ON and if you turned it OFF.",
    "APN name + MMSC URL from check_apn_settings (or confirm you reset APN and rebooted).",
    "VPN/Data Saver statuses and any changes made.",
    "Messaging app permissions status and any permissions granted.",
    "can_send_mms result and whether an MMS finally went through."
  ],
  "notes": [
    "No charges for any of these steps.",
    "If any step is unclear, tell me where you’re stuck and I’ll guide you through it."
  ]
}

