messages.content:
{
  "message": "Great work turning Airplane Mode off. You’ve got strong 5G signal and mobile data ON, but no browsing. That usually means the phone-side Data Roaming toggle is OFF, a 5G roaming quirk, or a settings conflict (VPN/Data Saver/APN). Let’s fix it step by step.",
  "first_questions": [
    "Are you on Android or iPhone?"
  ],
  "steps": [
    {
      "step": 1,
      "title": "Make sure Data Roaming is ON (phone setting)",
      "why": "Your account is roaming-enabled, but the phone also needs its own Data Roaming switch ON while abroad.",
      "android": [
        "Settings > Network & Internet (or Connections) > Mobile Network.",
        "Turn ON Data Roaming."
      ],
      "iphone": [
        "Settings > Cellular (or Mobile Data) > Cellular Data Options.",
        "Turn ON Data Roaming."
      ],
      "then": "Keep Wi‑Fi OFF and try loading example.com again."
    },
    {
      "step": 2,
      "title": "Refresh the data session",
      "why": "Toggling can re-establish the roaming data session.",
      "do": [
        "Turn Mobile Data OFF, wait 5 seconds, then turn it back ON.",
        "Try browsing again."
      ]
    },
    {
      "step": 3,
      "title": "Temporarily prefer LTE/4G (avoid 5G while roaming)",
      "why": "Some roaming partners have issues with 5G data. LTE/4G is often more reliable abroad.",
      "android": [
        "Settings > Mobile Network > Network Mode/Preferred Network Type.",
        "Select LTE/4G only (or LTE/4G preferred)."
      ],
      "iphone": [
        "Settings > Cellular > Cellular Data Options > Voice & Data.",
        "Select LTE (toggle off 5G Auto/On if available)."
      ],
      "then": "Try browsing again."
    },
    {
      "step": 4,
      "title": "Eliminate common blockers",
      "why": "VPNs and Data Saver can block/shape traffic, causing ‘no connection’.",
      "do": [
        "If a VPN is ON, disconnect it.",
        "Ensure Data Saver/Low Data Mode is OFF.",
        "Try browsing again."
      ]
    },
    {
      "step": 5,
      "title": "Reset APN to default and reboot",
      "why": "Incorrect APN can block data on roaming networks. Resetting restores the correct settings.",
      "android": [
        "Settings > Mobile Network > Access Point Names.",
        "Menu (⋮) > Reset to default.",
        "Reboot the phone.",
        "After reboot, keep Wi‑Fi OFF and try browsing."
      ],
      "iphone": [
        "Settings > General > Transfer or Reset > Reset > Reset Network Settings (this resets Wi‑Fi/BT/APN).",
        "Reboot occurs automatically.",
        "After reboot, keep Wi‑Fi OFF and try browsing."
      ]
    }
  ],
  "next_after_data_works": {
    "mms_test": [
      "Once a website loads over mobile data, send yourself a small photo MMS.",
      "If it fails, turn OFF Wi‑Fi Calling temporarily and retry the MMS."
    ]
  },
  "what_to_report_back": [
    "Your device type (Android or iPhone).",
    "Whether Data Roaming was OFF or ON when you checked.",
    "After each step: could you load a webpage over mobile data?",
    "Any error messages you see."
  ],
  "thought_process": "Because your line is active, roaming-enabled, and within data limits, the failure is almost certainly a device-side roaming/data configuration issue. We’ll first ensure the Data Roaming toggle is ON, then stabilize the connection by preferring LTE/4G, rule out VPN/Data Saver, and finally reset APN if needed. Once browsing works, MMS should work too; if not, we’ll address MMS-specific settings."
}

