messages.content:
{
  "thought_process": "Your line is Active and billing is clear, so No Signal/Data Disabled now points to the phone not registering on the network or mobile data being OFF. We’ll refresh the radio, verify SIM status, ensure data is ON, and confirm network mode/APN.",
  "steps": [
    {
      "title": "Refresh the network radio",
      "do": [
        "Turn Airplane Mode ON for 10 seconds, then turn it OFF.",
        "Wait about 60 seconds to see if signal bars appear."
      ],
      "why": "Forces the device to re-register to the network after the account change."
    },
    {
      "title": "Check overall network status",
      "do": [
        "Run check_network_status and tell me what it shows for: Airplane Mode, Signal strength, Network type (5G/4G/etc.), Mobile data (ON/OFF), Data roaming (ON/OFF)."
      ],
      "why": "Confirms the phone’s view of connectivity and whether data is actually disabled."
    },
    {
      "title": "Turn Mobile Data ON",
      "do": [
        "Go to Settings > Mobile/Cellular and turn Mobile Data ON (or use toggle_data to enable)."
      ],
      "why": "‘Data Disabled’ indicates the data switch is OFF. Enabling it restores data once signal returns."
    },
    {
      "title": "Check SIM status",
      "do": [
        "Run check_sim_status and tell me if it says Active, Missing, or Locked.",
        "If Missing: power OFF the phone, remove and carefully reinsert the SIM, then power ON (reseat_sim_card).",
        "If Locked (PIN/PUK): stop and tell me—don’t guess codes."
      ],
      "why": "If the SIM isn’t detected or is locked, the phone can’t register on the network."
    },
    {
      "title": "Verify preferred network mode",
      "do": [
        "Run check_network_mode_preference.",
        "If it shows 2G/3G-only, change it to 4g_5g_preferred using set_network_mode_preference."
      ],
      "why": "Older modes can prevent a stable connection or show no service in some areas."
    },
    {
      "title": "If still no signal: reseat and reboot",
      "do": [
        "Even if SIM shows Active, power OFF, remove and reinsert the SIM, power ON (reseat_sim_card), then reboot_device."
      ],
      "why": "A fresh SIM-to-device handshake often fixes registration issues."
    },
    {
      "title": "APN sanity check (for data once signal appears)",
      "do": [
        "Run check_apn_settings.",
        "If it shows Incorrect or missing MMSC, run reset_apn_settings and then reboot_device."
      ],
      "why": "Incorrect APN won’t cause ‘No Signal’ but will keep data from working normally."
    },
    {
      "title": "Environment check",
      "do": [
        "If you’re deep indoors, step outside for a minute and see if any bars appear."
      ],
      "why": "Poor indoor coverage can delay re-registration."
    }
  ],
  "please_reply_with": [
    "The exact outputs of check_network_status (especially signal strength and whether Mobile Data shows ON after you enable it).",
    "The result of check_sim_status (Active/Missing/Locked).",
    "The current network mode from check_network_mode_preference.",
    "Whether reseating the SIM and rebooting changed anything."
  ],
  "next_action_after_your_reply": "Based on those results, I’ll provide the precise next fix or escalate if needed."
}

