messages.content:
{
  "message": "I can help get your mobile data back to excellent speed. First, I need to verify your account to check your line status, data usage vs. plan limit, and roaming settings. In parallel, please run a few quick checks on your phone so we can isolate whether it’s a device setting, coverage, or account issue.",
  "why_these_steps": "Slow or dropping data is most often caused by: mobile data switch off, weak signal/coverage, Data Saver or VPN throttling, being locked to older network modes (2G/3G), hitting your data limit, roaming settings, or a suspended line. We’ll rule out device-side causes while I check your account once identified.",
  "need_verification": "Please provide ONE of the following to locate your account: 1) the phone number on the affected line, or 2) your customer ID, or 3) your full name and date of birth (YYYY-MM-DD).",
  "questions": [
    "Does the issue happen everywhere or only in certain places?",
    "Right now, are you on Wi‑Fi or using mobile data only?",
    "Are you currently traveling outside your home network/country?",
    "What do you see in the status bar: 5G/4G/LTE/3G/2G and how many bars?",
    "Do you use a VPN?",
    "About when did this start?"
  ],
  "guided_checks": [
    {
      "action": "check_status_bar",
      "what_to_report": "Copy any icons you see (e.g., ✈️ Airplane Mode, 📶 bars, 5G/4G, 🔽 Data Saver).",
      "why": "Confirms signal strength and whether Airplane Mode or Data Saver is affecting connectivity."
    },
    {
      "action": "check_network_status",
      "what_to_report": "Is mobile data enabled? What network type and signal strength are shown? Is data roaming ON or OFF?",
      "why": "Verifies that mobile data is actually on and whether roaming might be needed."
    },
    {
      "action": "run_speed_test",
      "what_to_report": "Download speed rating (unknown/very poor/poor/fair/good/excellent).",
      "why": "Measures current data performance so we can target improvements to excellent."
    },
    {
      "action": "check_network_mode_preference",
      "what_to_report": "Current preference (e.g., 5G preferred, 4G only, 3G/2G).",
      "why": "We’ll switch to 4g_5g_preferred if it’s on 2G/3G, which are too slow."
    },
    {
      "action": "check_data_restriction_status",
      "what_to_report": "Is Data Saver ON? Any global background data restrictions?",
      "why": "Data Saver can throttle or pause background traffic."
    },
    {
      "action": "check_vpn_status",
      "what_to_report": "Is a VPN connected?",
      "why": "VPNs can significantly slow or interrupt data."
    }
  ],
  "what_i_will_do_after_verification": [
    "Check if your line is active or suspended.",
    "Check your current cycle data usage vs. your plan limit and any refueled data.",
    "Confirm roaming enablement on the line if you’re traveling, and enable it if needed (no cost).",
    "If you hit your data cap, we can refuel up to 2 GB at your plan’s per‑GB rate or discuss a plan change.",
    "If the line is suspended due to billing, I’ll help handle the overdue bill and resume the line."
  ],
  "next": "Please reply with your phone number (or other verification option) and the results of the checks above. If any step is unclear, tell me and I’ll guide you through it."
}

