messages.content:
{
  "summary": "Your line is Active and your SIM is unlocked. Since it still shows No Signal/Data Disabled, we’ll refresh network registration, ensure the phone prefers modern networks, and reseat the SIM if needed.",
  "why_these_steps": [
    "After a suspension/resume and SIM unlock, phones can get stuck without registering to the network until we refresh settings.",
    "Using 4G/5G preferred avoids falling back to older modes that may not be available in your area.",
    "A SIM reseat clears many post-resume registration glitches."
  ],
  "steps_in_order": [
    {
      "step": "1) Confirm and toggle Mobile Data",
      "how": "Settings > Network & internet > Mobile network (or SIMs) > ensure Mobile data is ON. Toggle it OFF, wait 5 seconds, then turn it ON again.",
      "reason": "Clears the Data Disabled indicator once the phone can register."
    },
    {
      "step": "2) Set Preferred Network to 4G/5G",
      "how": "Settings > Network & internet > Mobile network > Preferred network type > select 5G/4G (Auto/Preferred).",
      "reason": "Ensures the device connects to available modern networks."
    },
    {
      "step": "3) Refresh registration",
      "how": "Turn Airplane Mode ON for 10 seconds, then OFF. Wait 30–60 seconds.",
      "reason": "Forces the phone to re-register with the network after settings changes."
    },
    {
      "step": "4) Reseat the SIM",
      "how": "Power the phone OFF. Remove the SIM tray, gently remove and reinsert the SIM, reinsert the tray, then power ON. Wait 60 seconds after boot.",
      "reason": "Fixes recognition/registration issues that can persist after a lock/unlock."
    },
    {
      "step": "5) Reset APN if still no signal",
      "how": "Settings > Network & internet > Mobile network > Access Point Names > use Reset to default. Then reboot the phone.",
      "reason": "Incorrect APN can block connectivity; resetting restores defaults."
    }
  ],
  "please_report_back": [
    "After step 3: do you see any signal bars or a network indicator (4G/5G/LTE)?",
    "If not, after step 4 (SIM reseat), check again and tell me what the status bar shows.",
    "If you do step 5, confirm you rebooted and what the status bar shows afterward."
  ],
  "note": "If the phone ever prompts again for a SIM PIN/PUK during these steps, stop and tell me before retrying so I can assist."
}

