messages.content:
{
  "acknowledgement": "Thanks for sticking with this, and I’m sorry this is still not working. Since you’ve enabled data/roaming, reset APN (and rebooted), and turned Wi‑Fi Calling off, the remaining likely causes are either general mobile data still not actually coming up on the device, an APN/MMSC entry not restored correctly, data restrictions/VPN, network mode, or messaging app permissions.",
  "what_we_want_to_verify_first": [
    {
      "check": "General mobile data is working now",
      "how": "With Wi‑Fi OFF, open a browser and load any website. Also run run_speed_test and share the result.",
      "why": "If web browsing fails or speed test shows no connection, MMS won’t work. We’d then focus on bringing data up first."
    },
    {
      "check": "APN settings include a valid MMSC URL",
      "how": "Run check_apn_settings and share the current APN name and MMSC URL value.",
      "why": "A missing/incorrect MMSC URL blocks MMS even if data is working."
    },
    {
      "check": "Messaging app has required permissions",
      "how": "Run check_app_permissions(app_name=\"messaging\") and share which permissions are granted.",
      "why": "The app must have storage and sms permissions for MMS."
    }
  ],
  "quick_fixes_to_try_now": [
    {
      "step": "Refresh the cellular data session",
      "actions": [
        "toggle_data (turn OFF), wait 10 seconds, then toggle_data (turn ON)"
      ],
      "why": "Re-establishes the data PDP context, which MMS depends on."
    },
    {
      "step": "Airplane mode refresh",
      "actions": [
        "toggle_airplane_mode (turn ON), wait 20 seconds, then toggle_airplane_mode (turn OFF)"
      ],
      "why": "Forces a full radio re-registration after roaming changes."
    },
    {
      "step": "Ensure best network mode",
      "actions": [
        "check_network_mode_preference",
        "If not already, set_network_mode_preference(\"4g_5g_preferred\")"
      ],
      "why": "MMS is unreliable on older modes; ensuring 4G/5G preferred helps."
    },
    {
      "step": "Disable any VPN",
      "actions": [
        "check_vpn_status",
        "If connected, disconnect_vpn"
      ],
      "why": "VPNs can interfere with MMS/data routing."
    },
    {
      "step": "Turn off Data Saver/restrictions",
      "actions": [
        "check_data_restriction_status",
        "If Data Saver is ON, toggle_data_saver_mode (turn OFF)"
      ],
      "why": "Data Saver can block background data that MMS uses."
    },
    {
      "step": "Confirm MMSC and reboot if changed",
      "actions": [
        "check_apn_settings",
        "If MMSC URL is missing or blank, run reset_apn_settings again, then reboot_device"
      ],
      "why": "Some devices need a second APN reset for MMSC to populate correctly."
    },
    {
      "step": "Grant messaging app permissions",
      "actions": [
        "check_app_permissions(app_name=\"messaging\")",
        "If missing, grant_app_permission(app_name=\"messaging\", permission=\"storage\")",
        "Also grant_app_permission(app_name=\"messaging\", permission=\"sms\")"
      ],
      "why": "Without storage and sms permissions, MMS sends can fail."
    }
  ],
  "after_each_batch_of_steps": [
    "Run check_network_status and share the output (signal, network type, data ON, roaming ON).",
    "Try loading a website with Wi‑Fi OFF.",
    "Run can_send_mms and try sending a test MMS."
  ],
  "please_reply_with": [
    "check_network_status output",
    "run_speed_test result",
    "check_apn_settings (confirm whether MMSC URL is now set)",
    "check_app_permissions(app_name=\"messaging\") output",
    "can_send_mms result after trying the above"
  ],
  "note": "Your line has roaming enabled and 2 GB of refueled data, so once the device session/APN/permissions are correct, MMS should start working. If data still won’t come up at all after these steps, we’ll proceed to reseat_sim_card and check_sim_status next."
}

