messages.content:
{
  "message": "You did everything right. The good news is your phone now shows strong 5G, so service and data are fine. When MMS still fails with good signal, the most common remaining cause is a phone setting: either Wi‑Fi Calling/VPN interference or the MMS server setting (APN/MMSC) needing a reset. We’ll fix those now, step by step.",
  "what_we_already_fixed": [
    "Roaming is enabled on your line for France.",
    "You have extra data (2 GB) so MMS isn’t blocked by your plan.",
    "Your phone is now on a fast network (5G)."
  ],
  "next_steps_detailed": [
    {
      "title": "Turn OFF Wi‑Fi Calling (just for this test)",
      "why": "Some carriers don’t carry MMS over Wi‑Fi Calling while abroad.",
      "steps": [
        "Open Settings.",
        "Tap Network & Internet (or Connections).",
        "Tap Wi‑Fi Calling.",
        "Turn Wi‑Fi Calling OFF."
      ],
      "note": "If you don’t see Wi‑Fi Calling, skip this step."
    },
    {
      "title": "Make sure any VPN is OFF",
      "why": "A VPN can block or slow MMS routing.",
      "steps": [
        "Settings > Network & Internet > VPN.",
        "If a VPN shows Connected, tap it and Disconnect.",
        "If you use a VPN app, open it and turn it OFF."
      ]
    },
    {
      "title": "Turn OFF Data Saver (if it’s ON)",
      "why": "Data Saver can interfere with background data that MMS needs.",
      "steps": [
        "Settings > Network & Internet (or Connections).",
        "Tap Data Saver (or Data usage > Data Saver).",
        "Turn Data Saver OFF."
      ]
    },
    {
      "title": "Reset APN to Default (refreshes the MMS server settings)",
      "why": "The MMSC (MMS server) entry can be missing/incorrect when roaming. Resetting restores the correct values.",
      "steps": [
        "Settings > Network & Internet (or Connections) > Mobile network (or SIMs).",
        "Tap Access Point Names (APN).",
        "Tap the three dots/menu > Reset to default > Confirm.",
        "You should see a single default APN selected after this."
      ]
    },
    {
      "title": "Restart your phone",
      "why": "Applies the new APN settings.",
      "steps": [
        "Hold the power button.",
        "Tap Restart and wait for it to fully start up.",
        "Confirm the top shows 4G/LTE/5G again and no airplane icon."
      ]
    },
    {
      "title": "Test MMS again",
      "steps": [
        "Keep Wi‑Fi OFF for this test.",
        "Confirm Mobile data ON and Data roaming ON.",
        "Open Messages, attach a photo, and Send."
      ]
    }
  ],
  "if_still_not_sending": {
    "more_checks": [
      {
        "title": "Give the Messages app the needed permissions",
        "steps": [
          "Settings > Apps > Messages.",
          "Tap Permissions.",
          "Allow: SMS and Storage/Files & media (or Photos and videos)."
        ]
      },
      {
        "title": "Make sure Messages is your default SMS app",
        "steps": [
          "Settings > Apps > Default apps.",
          "Tap SMS app and choose Messages."
        ]
      }
    ],
    "request": "If it still fails, tell me exactly what happens (any error message) and what the status bar shows (4G/LTE/5G). I’ll adjust the next steps right away."
  },
  "reassurance": "You’re not doing anything wrong, and none of these steps will delete anything on your phone. We’re just switching off features that can interfere and refreshing the MMS server settings.",
  "request_update": "Please go through the steps in order and let me know: did the picture send after the restart? What do you see at the top (4G/LTE/5G) and any error shown in Messages?"
}

