      ],
      "what_to_report": "Does it show SIM present/active, missing, or locked?",
      "why": "If the SIM isn’t detected or is locked, the phone can’t register. If Missing/Locked, skip to the Reseat SIM step below."
    },
    {
      "name": "Set preferred network mode to 4G/5G",
      "how": [
        "Go to Settings > Mobile/Cellular Network > Preferred network type (or Network mode) and choose 4G/5G preferred.",
        "Avoid 2G/3G-only modes."
      ],
      "why": "Ensures the phone tries compatible roaming networks that support data/MMS."
    },
    {
      "name": "Manual network selection",
      "how": [
        "Go to Settings > Mobile/Cellular Network > Network operators.",
        "Turn OFF Automatic, wait for the scan to finish.",
        "In France, try selecting: Orange F first, then SFR, then Bouygues Telecom, then Free Mobile.",
        "If one says ‘Unable to register’ or ‘Forbidden’, try the next. After you connect, you can leave it on that network or switch Automatic back ON."
