      "name": "Reboot the phone",
      "how": [
        "Power the phone off, wait 20 seconds, power it back on.",
        "After restart, give it 2–3 minutes near a window/open area to register."
      ],
      "why": "Refreshes the radio stack and often resolves registration after changes."
    },
    {
      "name": "Reseat the SIM (only if still No Signal)",
      "how": [
        "Power off the phone.",
        "Remove the SIM tray, take the SIM out, inspect for dust/debris, reinsert firmly.",
        "Power back on and wait 2–3 minutes for registration."
      ],
      "why": "Fixes poor contact or recognition issues preventing network attachment."
    }
