messages.content:
{
  "thought_process": "Your phone says “No SIM card detected,” so the network can’t register. We need to confirm whether you use a physical SIM (tray) or an eSIM profile and then get it recognized.",
  "two_quick_checks": [
    "Physical check for a SIM tray on the phone’s edge.",
    "Software check in Android settings to see if an eSIM/line is listed."
  ],
  "steps": {
    "physical_check": [
      "Inspect the phone’s edges for a thin rectangular tray with a tiny pinhole. Use a flashlight if needed.",
      "If you see a tray: power the phone OFF, insert a SIM tool/paperclip into the pinhole to eject it, and confirm a SIM card is present on the tray."
    ],
    "settings_check": [
      "On Android: Settings > Network & Internet (or Connections) > SIMs (or SIM manager).",
      "Tell me what you see: options like ‘SIM 1’, ‘Add eSIM’/‘Download a SIM’, or ‘No SIMs’.",
      "Also check Settings > About phone > Status > SIM status and Settings > About phone > IMEI info. If you see an entry like “IMEI (eSIM)” or a toggle for your carrier line, that points to eSIM capability."
    ]
  },
  "what_each_result_means_and_next_actions": [
    {
      "result": "Tray found with a physical SIM present",
      "next": [
        "While powered OFF, remove the SIM, gently wipe contacts, reinsert snugly (try the other SIM slot if available), power ON, wait 60 seconds, then check for signal and try data/MMS."
      ]
    },
    {
      "result": "Tray found but empty",
      "next": [
        "Likely using eSIM or no SIM installed. Go to Settings > SIMs/SIM manager and see if a carrier line/eSIM is listed and turned ON.",
        "If no line is listed, tell me—your eSIM may need re‑provisioning."
      ]
    },
    {
      "result": "No tray found; Settings shows a carrier line with a toggle",
      "next": [
        "Turn the line’s toggle ON (if OFF), wait ~60 seconds, then check for signal and test data/MMS."
      ]
    },
    {
      "result": "No tray found; Settings shows ‘Add eSIM’/‘Download a SIM’ and no active line",
      "next": [
        "Your eSIM profile isn’t present. Tell me and I’ll arrange eSIM re‑provisioning."
      ]
    },
    {
      "result": "SIM status shows Locked (PIN/PUK)",
      "next": [
        "Stop and tell me—I’ll escalate for SIM security assistance."
      ]
    }
  ],
  "safety_notes": [
    "Power OFF before ejecting/reinserting a physical SIM.",
    "Keep the SIM/tray aligned and avoid bending the SIM."
  ],
  "please_confirm": [
    "Do you see a SIM tray? If yes, was there a SIM card and were you able to reseat it?",
    "In Settings > SIMs/SIM manager, do you see your carrier line listed, a toggle to enable it, or only an option like ‘Add eSIM’?",
    "What does Settings > About phone > IMEI info show (any ‘IMEI (eSIM)’ entry)?"
  ]
}

