    "device_type": "Are you using an iPhone or an Android phone?",
    "quick_answers": [
      "Can normal texts (SMS without pictures) send/receive?",
      "Do you see a VPN/key icon at the top of your screen?"
    ]
  },
  "steps": [
    {
      "title": "Turn Wi‑Fi OFF temporarily",
      "why": "MMS uses mobile data; turning Wi‑Fi off helps us confirm mobile data works while roaming.",
      "iphone": "Settings > Wi‑Fi > toggle OFF.",
      "android": "Settings > Network & Internet (or Connections) > Wi‑Fi > toggle OFF."
    },
    {
      "title": "Make sure Mobile Data is ON",
      "why": "MMS requires mobile data even if you have SMS service.",
      "iphone": "Settings > Cellular/Mobile Data > toggle Cellular Data ON.",
      "android": "Settings > Network & Internet (or Connections) > Mobile network > toggle Mobile data ON."
    },
    {
      "title": "Turn Data Roaming ON (phone setting)",
      "why": "You’re abroad; roaming must be ON on the device as well.",
      "iphone": "Settings > Cellular > Cellular Data Options > Data Roaming > ON.",
      "android": "Settings > Network & Internet (or Connections) > Mobile network > Data roaming > ON."
    },
    {
      "title": "Turn OFF Wi‑Fi Calling (for now)",
      "why": "Some setups block MMS over Wi‑Fi Calling.",
      "iphone": "Settings > Cellular > Wi‑Fi Calling > OFF.",
      "android": "Phone app > ⋮ > Settings > Wi‑Fi Calling > OFF (or Settings > Network & Internet > SIM settings > Wi‑Fi Calling > OFF)."
    },
    {
      "title": "Ensure network mode is 4G/5G",
      "why": "2G is not suitable for MMS.",
      "iphone": "Settings > Cellular > Cellular Data Options > Voice & Data > select 4G or 5G.",
      "android": "Settings > Mobile network > Preferred network type > 4G/5G (avoid 2G/3G only)."
    },
    {
      "title": "Quick refresh of the data connection",
      "why": "Resets the data session while roaming.",
      "both": "Turn Mobile Data OFF, wait 10 seconds, then ON again."
    },
    {
      "title": "Test mobile internet",
      "why": "Confirms data works while roaming.",
      "both": "With Wi‑Fi still OFF, open a browser and load any website (e.g., example.com). Tell me if it loads."
    },
    {
      "title": "Try sending an MMS now",
      "why": "Check if the above resolved it.",
      "both": "Send a single photo to a contact or to yourself and report what happens."
    },
    {
      "title": "If still failing: reset APN to defaults",
      "why": "Incorrect MMSC/APN is a common MMS blocker.",
      "iphone": "Settings > Cellular > Cellular Data Network > tap Reset Settings (if available). If not visible, APN resets with a carrier settings update; we can prompt that after reboot.",
      "android": "Settings > Mobile network > Access Point Names > ⋮ > Reset to default. Ensure only the carrier APN remains selected."
    },
    {
      "title": "Reboot the phone",
      "why": "Applies APN changes and refreshes network registration.",
      "both": "Power off, wait 20 seconds, power back on. Then retry sending an MMS."
    },
    {
      "title": "If it still won’t send: check VPN and Data Saver",
      "why": "Both can interfere with MMS/data.",
      "vpn": "If you see a key icon or use a VPN app, open it and disconnect.",
      "data_saver": "iPhone: Settings > Cellular > Cellular Data Options > Low Data Mode OFF. Android: Settings > Network & Internet > Data Saver > OFF."
    },
    {
      "title": "If on Android: check messaging app permissions",
      "why": "The app needs storage/SMS permissions to send media.",
      "android": "Settings > Apps > Messages (your SMS app) > Permissions > Allow Storage/Photos and SMS."
    }
    ],
  "what_i_found_on_your_account": {
    "line_status": "Active",
    "roaming_on_carrier_side": true,
    "plan_data": "8.7 GB used of 15 GB; cycle ends 2025-02-28"
  },
  "next": "Please tell me whether you’re on iPhone or Android, then work through Steps 1–3 first and try an MMS. If it still fails, continue in order and let me know exactly where something doesn’t match or what result you see (e.g., web page loads or not, any error in Messages). I’ll adjust the guidance based on what you report."
}

