messages.content:
{
  "thought_process": "Airplane Mode being ON explained the earlier issue. Now that it’s OFF, your phone should register on a local network in France. Seeing “No Signal” means it hasn’t registered yet. Common causes: SIM not detected/locked, network mode set to an incompatible option, or the device just needs a quick refresh while roaming. We’ll check SIM status first, then network mode, then ensure data roaming is on, and finally reboot if needed.",
  "do_this_in_order": [
    {
      "title": "Give it up to 60–90 seconds",
      "why": "Sometimes it takes a short while to find and register on a roaming network after turning Airplane Mode off.",
      "what_to_watch": "See if any bars appear or if an ‘R’ (roaming) shows next to the bars."
    },
    {
      "title": "Confirm Airplane Mode is OFF",
      "how": "Swipe down twice for Quick Settings and make sure the Airplane icon is not highlighted."
    },
    {
      "title": "Check SIM status",
      "why": "If the SIM is missing or locked, the phone can’t connect to any network.",
      "android_path": "Settings > About phone > Status > SIM status (or Settings > Network & Internet > SIMs > SIM status).",
      "tell_me": "What does it say for SIM status? Options we often see are: Active/Connected, No SIM/Missing, SIM locked (PIN/PUK), or Not registered."
    },
    {
      "title": "Ensure preferred network mode is modern (4G/5G)",
      "why": "Older modes can prevent proper roaming.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type.",
      "set_to": "4G/5G (avoid 2G/3G only).",
      "tell_me": "What was it set to, and what did you change it to?"
    },
    {
      "title": "Turn ON Mobile Data and Data Roaming (important abroad)",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network.",
      "make_sure": [
        "Mobile data = ON",
        "Data roaming = ON (accept any prompt)"
      ]
    },
    {
      "title": "Reboot the phone",
      "why": "Forces a fresh registration with roaming networks.",
      "how": "Power off completely, wait 20 seconds, power back on.",
      "after_reboot": "Wait 60 seconds and check if bars/network type appear."
    }
  ],
  "special_cases_next_steps": [
    {
      "case": "If SIM status says No SIM/Missing",
      "action": "Reseat the SIM",
      "how": "Power off the phone, remove and reinsert the SIM card carefully, then power on. If you’re using an eSIM (no physical SIM tray), skip reseating and just reboot."
    },
    {
      "case": "If SIM status says SIM locked",
      "action": "Do not guess the PIN/PUK",
      "next": "Tell me what it shows. I’ll escalate to a human agent to help with SIM security."
    }
  ],
  "what_to_reply_with": [
    "What does SIM status show (Active/No SIM/SIM locked/Not registered)?",
    "What was your Preferred network type set to before, and what is it now?",
    "After the reboot, do you see any signal bars or an ‘R’ symbol? Any network type like 4G/LTE/5G?",
    "If still No Signal, please confirm that Mobile data and Data roaming are both ON."
  ]
}

