messages.content:
{
  "thought_process": "Great progress—your phone is now on 5G with full bars, so service and roaming are good. When MMS still fails at this point, the common culprits are: Wi‑Fi Calling interfering, Data Saver restricting data, or APN/MMSC settings needing a reset. Less commonly, the messaging app lacks permissions. We’ll rule these out in order.",
  "steps_in_order": [
    {
      "title": "Turn Wi‑Fi Calling OFF (temporarily)",
      "why": "Some setups block MMS over Wi‑Fi Calling.",
      "android_path": "Phone app > ⋮ (menu) > Settings > Wi‑Fi Calling > OFF (or Settings > Network & Internet > SIM settings > Wi‑Fi Calling > OFF)"
    },
    {
      "title": "Turn Data Saver OFF",
      "why": "Data Saver can block MMS/background data.",
      "android_path": "Settings > Network & Internet > Data Saver > OFF",
      "also_check": "Settings > Apps > Messages (or your SMS app) > Mobile data & Wi‑Fi > enable ‘Unrestricted data’ (or ‘Allow background data’)."
    },
    {
      "title": "Reset APN to default",
      "why": "Incorrect or missing MMSC in APN often breaks MMS.",
      "android_path": "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names > ⋮ > Reset to default",
      "note": "After reset, ensure only the carrier APN is selected (if multiple show)."
    },
    {
      "title": "Reboot the phone",
      "why": "Applies APN changes and refreshes registration.",
      "how": "Power off, wait 20 seconds, power back on. Wait 60 seconds after boot."
    },
    {
      "title": "Confirm key toggles and test",
      "check": [
        "Mobile data = ON",
        "Data roaming = ON",
        "Wi‑Fi = OFF (just for this test)"
      ],
      "tests": [
        "Open a browser and load example.com (to confirm data works).",
        "Then send a single photo (MMS) to yourself or a contact."
      ]
    },
    {
      "title": "If it still fails: check messaging app permissions",
      "why": "The app needs access to media and SMS to send pictures.",
      "android_path": "Settings > Apps > Messages (or your SMS app) > Permissions > Allow Photos and videos (or Storage) and SMS"
    }
  ],
  "what_to_report_back": [
    "Was Wi‑Fi Calling ON or OFF before you changed it?",
    "Was Data Saver ON or OFF?",
    "Did you successfully reset the APN to default and reboot?",
    "After reboot, can you load a web page over mobile data?",
    "Does the MMS now send, or is there an error message?"
  ],
  "next_if_still_not_working_after_all_above": "Tell me the exact error you see in the messaging app after the APN reset and reboot. If needed, we can try another APN selection if multiple are present, or I can escalate to issue a carrier settings refresh."
}

