  "actions_taken": [
    "Enabled international roaming on your line 555-123-2002."
  ],
  "next_steps_for_you": [
    "Tell me how much data you’d like me to add now: 1 GB ($2) or 2 GB ($4). I’ll apply it immediately.",
    "Then I’ll guide you to quickly verify the phone settings and test MMS."
  ],
  "questions": [
    "Would you like me to add 1 GB or 2 GB of data now?",
    "Do you recognize whether your phone matches the iPhone or Android description above?"
  ]
}

