messages.content:
{
  "reassurance": "You spotted it correctly—the airplane icon means Airplane Mode is ON. That blocks all cellular connections, so MMS can’t send. Turning it OFF is safe and is the right next step. I’ll guide you slowly and nothing here can harm your phone.",
  "why_this_matters": "Airplane Mode disables cellular data and roaming. MMS needs mobile data. Since we just added 2 GB, once Airplane Mode is OFF and data/roaming are ON, MMS should work.",
  "steps": [
    {
      "title": "Turn OFF Airplane Mode",
      "iphone": [
        "Swipe down from the top‑right corner to open Control Center.",
        "Tap the airplane icon so it turns gray (OFF)."
      ],
      "android": [
        "Swipe down from the top to open Quick Settings.",
        "Tap the airplane icon to turn it OFF (it should no longer be highlighted)."
      ],
      "tip": "If you don’t see the icon right away, swipe down again to expand the Quick Settings/Control Center."
    },
    {
      "title": "Wait for signal, then enable Data and Roaming",
      "iphone": [
        "Open Settings > Cellular.",
        "Turn Cellular Data ON.",
        "Go to Cellular Data Options and turn Data Roaming ON."
      ],
      "android": [
        "Open Settings > Network & Internet (or Connections) > Mobile network.",
        "Turn Mobile Data ON.",
        "Turn Data Roaming ON."
      ]
    },
    {
      "title": "Test connection",
      "instructions": [
        "Temporarily keep Wi‑Fi OFF for this test.",
        "Wait ~30 seconds and check the top bar for signal bars plus a label like 4G/LTE/5G and possibly an ‘R’ for roaming (expected in France).",
        "Try loading any website in your browser.",
        "Then try sending a small photo MMS."
      ]
    }
  ],
  "what_to_expect": [
    "After turning Airplane Mode OFF, you should see signal bars return.",
    "With data and roaming ON, the website should load and MMS should send."
  ],
  "if_it_still_fails": [
    "Tell me exactly what you see in the status bar (e.g., signal bars, 4G/LTE/5G, an ‘R’).",
    "Let me know any message the messaging app shows.",
    "We can then quickly try turning Wi‑Fi Calling OFF and check one more setting."
  ],
  "questions": [
    "Are you on an iPhone or an Android? If you’re not sure, describe what your Settings app looks like and I’ll tailor the steps."
  ],
  "next": "Go ahead and turn Airplane Mode OFF now, then follow the Data and Roaming steps, and tell me what you see and whether the MMS sends."
}

