messages.content:
{
  "why_this_is_happening": "“No Signal” means the phone hasn’t connected to a local network yet, and “data disabled” means the Mobile Data switch is OFF. Because you’re abroad, you also need Data Roaming ON. We’ll turn these on and give the phone a moment to register.",
  "do_this_next": [
    {
      "title": "Turn ON Mobile Data",
      "iphone": [
        "Open Settings > Cellular.",
        "Turn Cellular Data ON."
      ],
      "android": [
        "Open Settings > Network & Internet (or Connections) > Mobile network.",
        "Turn Mobile data ON."
      ],
      "why": "MMS needs mobile data to work."
    },
    {
      "title": "Turn ON Data Roaming (since you’re in France)",
      "iphone": [
        "Settings > Cellular > Cellular Data Options.",
        "Turn Data Roaming ON."
      ],
      "android": [
        "Settings > Network & Internet (or Connections) > Mobile network.",
        "Turn Data roaming ON."
      ],
      "why": "Allows data on partner networks outside your home network."
    },
    {
      "title": "Wait and check the status bar",
      "steps": [
        "Keep Wi‑Fi OFF for this test.",
        "Wait 60–90 seconds.",
        "Look for signal bars plus a label like 4G/LTE/5G, and possibly an ‘R’ for roaming."
      ],
      "why": "The phone needs a moment to register on a local network."
    },
    {
      "title": "Test",
      "steps": [
        "Try loading any website in your browser.",
        "Then try sending a small photo MMS."
      ]
    },
    {
      "title": "If you still see “No Signal”",
      "steps": [
        "Toggle Airplane Mode ON for 10 seconds, then turn it OFF again.",
        "If still no signal, set Preferred Network Mode to 4G/5G (4g_5g_preferred).",
        "If it still doesn’t connect, restart your phone."
      ],
      "why": "These steps refresh the radio and ensure the phone can use modern networks."
    }
  ],
  "safety_notes": [
    "If you see a prompt for a SIM PIN/PUK at any point, stop and tell me.",
    "Nothing here will harm your phone; we’re just turning the correct switches on."
  ],
  "questions": [
    "Are you on an iPhone or an Android? I can tailor the on-screen labels for your exact device.",
    "After turning ON Mobile Data and Data Roaming, what do you see in the status bar now?"
  ],
  "what_i_expect_after_steps": "Once Mobile Data and Data Roaming are ON and the phone registers, you should see signal bars with 4G/LTE/5G and MMS should send."
}

