messages.content:
{
  "reassurance": "You’re not doing anything wrong. Your line is active, roaming is enabled on our side, and we added 2 GB. “No Signal” means the phone hasn’t registered on a local network yet. The next checks are safe and won’t erase anything.",
  "what_i_checked_on_our_side": [
    "Line 555-123-2002: Active",
    "Roaming on your line: Enabled",
    "Data top‑up: 2 GB added successfully"
  ],
  "why_these_steps": "If the phone still shows No Signal after the basics, the most common next causes are a SIM issue (missing/loose/locked) or the phone not fully refreshing its network registration. We’ll check the SIM status, reseat it if needed, and then try a quick data/roaming refresh.",
  "steps": [
    {
      "title": "Check SIM status on the phone",
      "iphone": [
        "Settings > Cellular.",
        "If you see messages like “No SIM” or “SIM Locked,” stop and tell me.",
        "If you see your carrier name or a SIM listed (e.g., “Primary”), that indicates the SIM is detected."
      ],
      "android": [
        "Settings > About phone > SIM status (sometimes under Status or Network).",
        "Check if it says SIM status: Active/Connected vs Missing/Not detected/Locked.",
        "If it shows Missing or Locked, stop and tell me."
      ]
    },
    {
      "title": "If SIM is Missing or not detected: reseat the SIM",
      "instructions": [
        "Power the phone OFF.",
        "If your phone has a physical SIM tray: eject the tray, gently remove and reinsert the SIM card, making sure it’s aligned correctly, then reinsert the tray.",
        "Power the phone ON again and wait 60–90 seconds.",
        "Keep Wi‑Fi OFF for the test and check if signal bars appear."
      ],
      "note": "If your phone is eSIM‑only (no physical tray), skip this and tell me—it may need a different check."
    },
    {
      "title": "If SIM is Active/detected: refresh data and roaming toggles",
      "instructions": [
        "Go to Settings > Cellular/Mobile Network.",
        "Turn Mobile Data OFF, wait 10 seconds, then turn it ON.",
        "Turn Data Roaming OFF, wait 10 seconds, then turn it ON.",
        "Wait 60–90 seconds and check the top bar for signal bars plus 4G/LTE/5G and possibly an ‘R’ (roaming)."
      ]
    },
    {
      "title": "Final quick refresh",
      "instructions": [
        "Turn Airplane Mode ON for 10 seconds, then OFF again.",
        "Wait 60 seconds and recheck the status bar.",
        "Try loading a website (with Wi‑Fi OFF), then try sending a small photo MMS."
      ]
    }
  ],
  "what_to_tell_me": [
    "Are you on an iPhone or an Android?",
    "What does the SIM status show (Active/Detected vs Missing/Locked)?",
    "After the steps above, what do you see in the status bar now (any bars, 4G/LTE/5G, an ‘R’, or still “No Signal”)?"
  ],
  "next_if_still_no_signal": "If the SIM is detected and we still get “No Signal” after reseating and refresh, I’ll escalate to a human specialist to run deeper roaming/provisioning checks on your line.",
  "safety": "All steps are safe and reversible. You won’t lose any data or content."
}

